var checks=new List<object>();var passed=0;var failed=0;
void Require(bool condition){if(!condition)throw new InvalidOperationException("Contract assertion failed.");}
void Throws<T>(Action action)where T:Exception{try{action();throw new InvalidOperationException("Expected exception.");}catch(T){}}
async Task Check(string name,Func<Task> action){try{await action();passed++;checks.Add(new{name,passed=true});}catch(Exception error){failed++;checks.Add(new{name,passed=false,error=error.GetType().FullName});}}
TenantChangeAuditPolicy Policy(TenantChangeAuditMode mode=TenantChangeAuditMode.BeforeAfterSnapshots,params TenantChangeFieldRule[] fields)
 =>new(mode,[new("document.update","write","document",fields.Length==0?[new("title"),new("enabled"),new("secret",true),new("unchanged")]:fields)]);
TenantChangeState State(params (string Name,TenantChangeValue Value)[] values)=>new(values.Select(x=>KeyValuePair.Create(x.Name,x.Value)));
TenantChangeStates States()=>new(State(("title",TenantChangeValue.Text("old")),("secret",TenantChangeValue.Text("private-before")),("unchanged",TenantChangeValue.Text("same")),("not-allowed",TenantChangeValue.Text("private-unknown"))),State(("title",TenantChangeValue.Text("new")),("secret",TenantChangeValue.Text("private-after")),("unchanged",TenantChangeValue.Text("same")),("enabled",TenantChangeValue.Boolean(true))));
TenantChangeReceipt Receipt(TenantOperationContext c,TenantChangeKind kind=TenantChangeKind.Update,string? mutation=null,Guid? id=null)=>new(id??Guid.NewGuid(),mutation=="principal"?new("issuer","other"):c.Identity.Principal,mutation=="scheme"?"Other":c.Identity.AuthenticationScheme,mutation=="tenant"?new("B"):c.Tenant,mutation=="operation"?"other.write":c.OperationId,mutation=="action"?"read":c.Action,mutation=="kind"?"other":c.Resource.Kind,mutation=="resource"?"other":c.Resource.ResourceId,mutation=="acl-version"?"acl-other":c.Resource.Version,kind,kind==TenantChangeKind.Create?null:"entity-v5",kind==TenantChangeKind.Delete?null:"entity-v6",DateTimeOffset.UnixEpoch);
