sealed class Clock:TimeProvider
{public DateTimeOffset Now=DateTimeOffset.Parse("2026-11-20T00:00:00Z");public long Timestamp;public override long TimestampFrequency=>TimeSpan.TicksPerSecond;public override DateTimeOffset GetUtcNow()=>Now;public override long GetTimestamp()=>Timestamp;public void Advance(TimeSpan elapsed){Now+=elapsed;Timestamp+=elapsed.Ticks;}}
sealed class Fixture:IIdentitySource,ITenantMembershipSource,IResourceScopeSource,ITenantAccessPolicy,ITenantAuditSink
{
 public Clock Clock{get;}=new();public int DataRevision;public List<TenantAuditEvent> Events{get;}=[];
 public ValueTask AppendAsync(TenantAuditEvent entry,CancellationToken token){Events.Add(entry);return ValueTask.CompletedTask;}
 public ValueTask<IdentitySnapshot?> ResolveAsync(CancellationToken token)=>ValueTask.FromResult<IdentitySnapshot?>(new(new("issuer","alice"),"Bearer",Clock.Now.AddMinutes(-1),Clock.Now.AddMinutes(10)));
 public ValueTask<TenantMembershipSnapshot?> ResolveAsync(IdentitySnapshot i,TenantId t,CancellationToken token)=>ValueTask.FromResult<TenantMembershipSnapshot?>(new(i.Principal,t,true,Clock.Now.AddMinutes(-1),Clock.Now.AddMinutes(10),"membership-v1"));
 public ValueTask<ResourceScopeSnapshot?> ResolveAsync(TenantId t,string k,string id,CancellationToken token)=>ValueTask.FromResult<ResourceScopeSnapshot?>(new(t,k,id,"acl-v1"));
 public ValueTask<bool> IsAllowedAsync(TenantAccessRequest r,CancellationToken token)=>ValueTask.FromResult(true);
 public async Task Run(Func<TenantOperationContext,Task> callback,string operation="document.update",string action="write",string kind="document",string id="entity-1")
 {var registry=new TenantOperationRegistryBuilder().Register<string,bool>(operation,action,kind,x=>x,x=>new(new("A"),x),()=>new Handler(callback)).Build();var services=new TenantSecurityServices(this,new(["issuer"],["Bearer"]),this,this,TimeSpan.FromMinutes(1),this,Clock,new(this));var result=await new TenantOperationDispatcher(registry,services).DispatchAsync<string,bool>(operation,id,new("fixture"));if(!result.IsSuccess)throw new InvalidOperationException("Fixture operation failed.");}
 public static TenantChangeReceipt UncheckedReceipt(string tenant="A")=>new(Guid.NewGuid(),new("issuer","alice"),"Bearer",new(tenant),"document.update","write","document","entity-1","acl-v1",TenantChangeKind.Update,"entity-v5","entity-v6");
 private sealed class Handler(Func<TenantOperationContext,Task> callback):ITenantOperationHandler<string,bool>
 {public async ValueTask<OperationResult<bool>> HandleAsync(string request,TenantOperationContext context,CancellationToken token){await callback(context);return OperationResult<bool>.Success(true);}}
}
sealed class Store:ITenantChangeAuditSink,ITenantChangeAuditHistorySource
{
 public static int Constructors;public Store(){Interlocked.Increment(ref Constructors);}
 public List<TenantChangeAuditRecord> Entries{get;}=[];public int AppendCalls,ReadCalls;public bool Fail;public Action? AfterAppend,AfterRead;public TimeSpan AppendDelay;
 public async ValueTask AppendAsync(TenantChangeAuditRecord record,CancellationToken token){AppendCalls++;if(AppendDelay>TimeSpan.Zero)await Task.Delay(AppendDelay);if(Fail)throw new IOException("Controlled fixture sink failure.");if(Entries.Any(x=>x.Receipt.ReceiptId==record.Receipt.ReceiptId))throw new InvalidOperationException("Duplicate receipt.");Entries.Add(record);AfterAppend?.Invoke();}
 public ValueTask<TenantChangeAuditPage> ReadAsync(TenantId tenant,int limit,string? cursor,CancellationToken token){ReadCalls++;AfterRead?.Invoke();return ValueTask.FromResult(new TenantChangeAuditPage(Entries));}
}

sealed class ThrowClock:TimeProvider{public override DateTimeOffset GetUtcNow()=>throw new IOException("Controlled trail clock failure.");}
